@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<Umbraco.Cms.Core.Models.Blocks.BlockGridItem<ImageBlock>>
@{
    var model = new ImageModel
    {
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1600),
        AltText = Model.Content.Caption ?? Model.Content.Image?.Name ?? "",
        Caption = Model.Content.Caption,
    };
}
@await Component.InvokeAsync("Image", new { model })
----
@model Umbraco.Bench.Umbraco.Models.Blocks.ImageModel

@if (Model.ImageUrl is not null)
{
    <figure class="mx-auto max-w-5xl px-6 py-8">
        <img src="@Model.ImageUrl" alt="@Model.AltText" loading="lazy" class="w-full rounded-2xl shadow-lg ring-1 ring-slate-900/10" />
        @if (!string.IsNullOrWhiteSpace(Model.Caption))
        {
            <figcaption class="mt-3 text-center text-sm text-slate-500">@Model.Caption</figcaption>
        }
    </figure>
}
